diff --git a/proto/telemetry/vehicle.proto b/proto/telemetry/vehicle.proto
--- a/proto/telemetry/vehicle.proto
+++ b/proto/telemetry/vehicle.proto
@@ -2,6 +2,6 @@
 package simulation.telemetry;
 message VehicleTelemetry {
   string vehicle_id = 1;
-  // Ground speed in meters per second.
-  float speed_mps = 2;
+  // Ground speed truncated to integer meters per second.
+  int32 speed_mps = 2;
 }
diff --git a/runtimes/python/telemetry_runtime.py b/runtimes/python/telemetry_runtime.py
--- a/runtimes/python/telemetry_runtime.py
+++ b/runtimes/python/telemetry_runtime.py
@@ -7,7 +7,7 @@

 def evaluate(request):
     entity = VehicleTelemetry.FromString(base64.b64decode(request['payload'], validate=True))
-    sample = VehicleTelemetry(vehicle_id=request['vehicle_id'], speed_mps=request['speed'])
+    sample = VehicleTelemetry(vehicle_id=request['vehicle_id'], speed_mps=int(min(2_147_483_647, max(-2_147_483_648, request['speed']))))
     fields = {'vehicle_id': entity.vehicle_id, 'speed_mps': entity.speed_mps}
     return {'fields': fields, 'speeding': entity.speed_mps > 30.0,
             'constructed_payload': base64.b64encode(sample.SerializeToString()).decode()}
diff --git a/runtimes/typescript/telemetry.ts b/runtimes/typescript/telemetry.ts
--- a/runtimes/typescript/telemetry.ts
+++ b/runtimes/typescript/telemetry.ts
@@ -6,7 +6,7 @@
   const requests: Request[] = JSON.parse(readFileSync(0, "utf8"));
   const results = requests.map(request => {
     const entity = VehicleTelemetry.decode(new Uint8Array(Buffer.from(request.payload, "base64")));
-    const sample = VehicleTelemetry.encode({ vehicleId: request.vehicle_id, speedMps: request.speed }).finish();
+    const sample = VehicleTelemetry.encode({ vehicleId: request.vehicle_id, speedMps: Math.trunc(Math.min(2_147_483_647, Math.max(-2_147_483_648, request.speed))) }).finish();
     const fields = { vehicle_id: entity.vehicleId, speed_mps: entity.speedMps };
     return { fields, speeding: entity.speedMps > 30.0, constructed_payload: Buffer.from(sample).toString("base64") };
   });
diff --git a/runtimes/csharp/Telemetry.cs b/runtimes/csharp/Telemetry.cs
--- a/runtimes/csharp/Telemetry.cs
+++ b/runtimes/csharp/Telemetry.cs
@@ -9,7 +9,7 @@
             new JsonSerializerOptions(JsonSerializerDefaults.Web)) ?? throw new JsonException("Missing requests");
         var results = requests.Select(request => {
             var entity = Simulation.Telemetry.VehicleTelemetry.Parser.ParseFrom(Convert.FromBase64String(request.Payload));
-            var sample = new Simulation.Telemetry.VehicleTelemetry { VehicleId = request.VehicleId, SpeedMps = (float)request.Speed };
+            var sample = new Simulation.Telemetry.VehicleTelemetry { VehicleId = request.VehicleId, SpeedMps = (int)Math.Clamp(request.Speed, int.MinValue, int.MaxValue) };
             var fields = new Dictionary<string, object> { ["vehicle_id"] = entity.VehicleId, ["speed_mps"] = entity.SpeedMps };
             return new { fields, speeding = entity.SpeedMps > 30.0, constructed_payload = Convert.ToBase64String(sample.ToByteArray()) };
         });
